#!/usr/bin/env python3
"""Original MIT SH-2 video-effect fixture. Adjacent LICENSE; no Sega objects.

ST-058-R2 §§5.3/6.1/6.3/6.4/8.1. The guest creates its own bitmap,
rotation/coefficient, line-scroll and line-window tables through real MMIO.
"""
import argparse
import hashlib
import importlib.util
from pathlib import Path
import struct
HERE = Path(__file__).resolve().parent
spec = importlib.util.spec_from_file_location('assembler', HERE.parents[1] / 'homebrew/star-collector/build.py')
assembler = importlib.util.module_from_spec(spec)
spec.loader.exec_module(assembler)

def store(address, value, width='w'):
    return f'load {address:#x},r1\nload {value:#x},r0\nmov.{width} r0,@r1\n'

def build():
    source = '; Original MIT rotation/line-effects guest. Generated by build_effects.py.\n'
    # Enable display last, after all tables are populated.
    for off, value in [(0xE,0x243),(0x18,0x4444),(0x1A,0xEEEE),
                       (0x20,0x11),(0x28,0x32),(0x2A,0x3200),(0x3C,2),
                       (0x70,504),(0x78,1),(0x7C,1),(0x9A,2),
                       (0xF8,3),(0xFC,4),(0xB0,2),(0xB4,3),(0xB6,3),
                       (0xC2,0),(0xC6,7),(0xC8,0),(0xCA,0),(0xCC,14),(0xCE,7),
                       (0xD0,2),(0xD4,8),(0xAC,3),(0xAE,0xF800)]:
        source += store(0x25F80000+off,value)
    for off, value in [(0xBC,0x38000),(0xA0,0x34000),(0xD8,0x80034800)]:
        source += store(0x25F80000+off,value,'l')
    # Independently authored four-color 8x8 bitmap, and an underlying red/green bitmap.
    colors=[0x801F,0x83E0,0xFC00,0xFFFF]
    for y in range(8):
        for x in range(8):
            source += store(0x25E00000+(y*512+x)*2,colors[(x+y)%4])
            source += store(0x25E40000+(y*512+x)*2,colors[x%2])
        source += store(0x25E68000+y*4,(y%2)<<16,'l')
        source += store(0x25E69000+y*4,(16+(y%2)*4)<<16 | (30-(y%2)*4),'l')
    # A: 90-degree transform (x,y)->(y,3-x); B: translate (x,y)->(x+1,y).
    for at in [0x70000,0x70080]:
        for off in [0x10,0x14,0x4C,0x50]: source+=store(0x25E00000+at+off,0x10000,'l')
    for off,value in [(0x20,0x10000),(0x28,0xFFFF0000),(0x48,3<<16),
                      (0x54,0),(0x5C,1<<16)]:
        source+=store(0x25E70000+off,value,'l')
    for off,value in [(0x1C,0x10000),(0x2C,0x10000),(0x44,0x10000)]:
        source+=store(0x25E70080+off,value,'l')
    for x in range(320):
        # Request A for first two screen columns, B for remaining columns.
        source+=store(0x25E60000+x*2,0x400 if x<2 else 0x8000)
    source+=store(0x25F80000,0x8000)
    source+=store(0x0600A000,0x600D,'l')+'park:\nsleep\nbra park\nnop\n'
    code=assembler.assemble(source,base=0x200)
    assert len(code)<0x10000
    rom=bytearray(524288)
    rom[:8]=struct.pack('>II',0x200,0x06100000)
    rom[0x200:0x200+len(code)]=code
    lines=['# Original MIT rotation/line-effects BIOS fixture. Adjacent LICENSE.',
           '# Generated from effects.s by build_effects.py; unspecified bytes zero.']
    for at in range(0,len(rom),16):
        chunk=rom[at:at+16]
        if any(chunk): lines.append(f'{at:04X} '+' '.join(f'{w:04X}' for w in struct.unpack('>8H',chunk)))
    return source,'\n'.join(lines)+'\n',hashlib.sha256(rom).hexdigest()

if __name__=='__main__':
    parser=argparse.ArgumentParser();parser.add_argument('--check',action='store_true');args=parser.parse_args()
    source,text,digest=build()
    for path,value in [(HERE/'effects.s',source),(HERE/'effects.hex',text)]:
        if args.check: assert path.read_text()==value,f'Rebuild {path.name}'
        else: path.write_text(value)
    print(f'{"Verified" if args.check else "Built"} effects.hex; expanded ROM SHA-256 {digest}')
